CREATE TABLE "WhatsAppChannel" ("id" TEXT PRIMARY KEY,"agencyId" TEXT NOT NULL REFERENCES "Agency"("id") ON UPDATE RESTRICT ON DELETE RESTRICT,"phoneId" TEXT NOT NULL UNIQUE,"wabaId" TEXT NOT NULL,"displayPhone" TEXT NOT NULL,"credentials" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT false,"revision" INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX "WhatsAppChannel_id_agencyId_key" ON "WhatsAppChannel"("id","agencyId");
CREATE TABLE "WhatsAppTemplate" ("id" TEXT PRIMARY KEY,"agencyId" TEXT NOT NULL,"channelId" TEXT NOT NULL,"name" TEXT NOT NULL,"language" TEXT NOT NULL,"body" TEXT NOT NULL,"status" TEXT NOT NULL,"parameterCount" INTEGER NOT NULL,"purpose" TEXT NOT NULL DEFAULT '',"slots" JSONB NOT NULL DEFAULT '[]',"revision" INTEGER NOT NULL DEFAULT 0,FOREIGN KEY("channelId","agencyId") REFERENCES "WhatsAppChannel"("id","agencyId") ON UPDATE RESTRICT ON DELETE RESTRICT);
CREATE UNIQUE INDEX "WhatsAppTemplate_channelId_name_language_key" ON "WhatsAppTemplate"("channelId","name","language");CREATE UNIQUE INDEX "WhatsAppTemplate_id_agencyId_key" ON "WhatsAppTemplate"("id","agencyId");
CREATE TABLE "MessagingConsent" ("id" TEXT PRIMARY KEY,"agencyId" TEXT NOT NULL,"phone" TEXT NOT NULL,"optedIn" BOOLEAN NOT NULL DEFAULT false,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "MessagingConsent_agencyId_phone_key" ON "MessagingConsent"("agencyId","phone");
CREATE TABLE "MessagingConsentEvent" ("id" TEXT PRIMARY KEY,"agencyId" TEXT NOT NULL,"phone" TEXT NOT NULL,"optedIn" BOOLEAN NOT NULL,"evidence" TEXT NOT NULL,"actor" TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX "MessagingConsentEvent_agencyId_phone_occurredAt_idx" ON "MessagingConsentEvent"("agencyId","phone","occurredAt");
CREATE TABLE "WhatsAppNotification" ("id" TEXT PRIMARY KEY,"agencyId" TEXT NOT NULL,"channelId" TEXT NOT NULL,"templateId" TEXT NOT NULL,"bookingId" TEXT NOT NULL,"purpose" TEXT NOT NULL,"occurrence" TEXT NOT NULL,"phone" TEXT NOT NULL,"parameters" JSONB NOT NULL,"templateRevision" INTEGER NOT NULL,"channelRevision" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'QUEUED',"providerMessageId" TEXT UNIQUE,"errorCode" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("channelId","agencyId") REFERENCES "WhatsAppChannel"("id","agencyId") ON UPDATE RESTRICT ON DELETE RESTRICT,FOREIGN KEY("templateId","agencyId") REFERENCES "WhatsAppTemplate"("id","agencyId") ON UPDATE RESTRICT ON DELETE RESTRICT,FOREIGN KEY("bookingId","agencyId") REFERENCES "Booking"("id","agencyId") ON UPDATE RESTRICT ON DELETE RESTRICT);
CREATE UNIQUE INDEX "WhatsAppNotification_business_key" ON "WhatsAppNotification"("agencyId","bookingId","purpose","occurrence");CREATE INDEX "WhatsAppNotification_agencyId_status_createdAt_idx" ON "WhatsAppNotification"("agencyId","status","createdAt");
CREATE TABLE "MessagingDeliveryEvent" ("id" TEXT PRIMARY KEY,"agencyId" TEXT NOT NULL,"notificationId" TEXT NOT NULL,"status" TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL);CREATE INDEX "MessagingDeliveryEvent_agencyId_notificationId_idx" ON "MessagingDeliveryEvent"("agencyId","notificationId");
